#!/usr/bin/env bash
#
# Xcode Cloud starts from a bare clone of the repository, which is missing two things
# the build needs: Vendor/ (the staged CPython, 53 MB and gitignored) and the project
# itself (generated by XcodeGen). Rebuild both before xcodebuild runs.
#
# The committed Pokeet.xcodeproj exists so Xcode Cloud has a project to attach a
# workflow to; regenerating here keeps the build in step with project.yml.
set -euo pipefail

cd "${CI_PRIMARY_REPOSITORY_PATH:-${CI_WORKSPACE:-$(dirname "$0")/..}}"

started=$SECONDS

printf '▸ Staging CPython\n'
scripts/fetch-python.sh

printf '▸ Generating Pokeet.xcodeproj\n'
if ! command -v xcodegen >/dev/null 2>&1; then
    brew install xcodegen
fi
xcodegen generate

printf '▸ ci_post_clone finished in %ss\n' "$((SECONDS - started))"
